    const call = (globalThis as { __dynCall?: Promise<unknown> }).__dynCall
    delete (globalThis as { __dynCall?: Promise<unknown> }).__dynCall
    await expect(call).resolves.toBe('pong')
    expect(bench.invoked).toEqual([{
